INSERT INTO locations (city_id, name, neighborhood, category, description, latitude, longitude, photo_url, vibe_difficulty, what_to_wear) VALUES

('11111111-0000-0000-0000-000000000001',
'Madison Avenue',
'Upper East Side',
'Old Money',
'The runway of the quietly rich. Walk slowly, carry nothing from a chain store, and maintain the expression of someone who just came from a board meeting they didn''t need to attend. The key is purposeful aimlessness — you''re not shopping, you''re simply existing in proximity to beautiful things.',
40.7749, -73.9644,
'https://images.unsplash.com/photo-1534430480872-3498386e7856?w=800&q=80',
3,
'{"men": {"brands": ["Loro Piana", "Brunello Cucinelli", "Patek Philippe", "Berluti"], "outfit": {"top": "Oatmeal cashmere crewneck or pale blue Oxford shirt, no tie", "bottom": "Dark navy straight-leg trousers, no break, impeccably pressed", "shoes": "Tan suede double-monk Berluti or clean chestnut loafers", "bag": "Slim tan leather document holder or nothing at all", "accessories": "Patek Philippe Calatrava in rose gold, no other jewelry whatsoever"}, "color_palette": "Navy, camel, oatmeal, tan — the entire palette of someone who winters in Gstaad without mentioning it", "budget_dupe": "Can''t do Loro Piana? Uniqlo cashmere + COS trousers + resoled vintage loafers gets you 80% there. Nobody checks labels on Madison, they check posture."}, "women": {"brands": ["The Row", "Celine", "Cartier", "Manolo Blahnik"], "outfit": {"top": "Ivory silk blouse or fine-knit camel turtleneck, perfectly tucked", "bottom": "Wide-leg cream or camel trousers, pressed with military precision", "shoes": "Pointed-toe kitten heel in nude suede or clean white New Balance 990 if doing ''off-duty''", "bag": "Celine Triomphe in tan or The Row half-moon bag", "accessories": "Cartier Love bracelet or Trinity ring, simple gold hoops, a silk scarf knotted loosely"}, "color_palette": "Cream, ivory, camel, bone — the palette of someone who dry-cleans everything including their thoughts", "budget_dupe": "Toteme for the trousers, & Other Stories for the blouse. One good secondhand Celine bag changes the entire read. Do not skip the bag."}}'::jsonb),

('11111111-0000-0000-0000-000000000001',
'The Bemelmans Bar at The Carlyle',
'Upper East Side',
'Continental',
'One of the last truly civilised rooms in New York. Order a martini, nurse it for two hours, and speak in a slightly lower register than you normally would. The Ludwig Bemelmans murals will make you feel like you belong here even if you absolutely do not. That''s the magic.',
40.7752, -73.9635,
'https://images.unsplash.com/photo-1543007630-9710e4a00a20?w=800&q=80',
4,
'{"men": {"brands": ["Tom Ford", "Brioni", "Cartier", "John Lobb"], "outfit": {"top": "Midnight navy blazer or dark suit jacket, white French-cuff shirt", "bottom": "Dark charcoal wool trousers, no break", "shoes": "Black cap-toe Oxfords or dark burgundy loafers, mirror shine", "bag": "No bag. A man at Bemelmans does not carry a bag.", "accessories": "Cartier Santos or vintage Rolex Datejust, pocket square in silk, no tie required but have one ready"}, "color_palette": "Midnight navy, charcoal, white, deep burgundy — the palette of a man who knows what hour is appropriate for a second drink", "budget_dupe": "A well-fitted navy suit from SuitSupply + John Lobb shoes from The RealReal is the move. The room is dark enough that the fabric won''t matter. The fit will."}, "women": {"brands": ["Carolina Herrera", "Oscar de la Renta", "Van Cleef & Arpels", "Aquazzura"], "outfit": {"top": "Silk blouse in ivory or dusty rose, something with a subtle pattern", "bottom": "Slim cigarette trousers or a midi skirt in deep navy or hunter green", "shoes": "Block-heel slingback or pointed-toe heel in black or nude", "bag": "Structured clutch or small top-handle bag, nothing with visible branding", "accessories": "Pearl earrings or a vintage brooch, thin gold chain, Van Cleef Alhambra if you have it"}, "color_palette": "Ivory, dusty rose, deep navy, forest green — cocktail hour colors from a different era", "budget_dupe": "A vintage silk blouse from a good consignment store plus a well-cut trouser from Banana Republic (yes, really — the monochrome thing hides the label). Pearls can be faux, no one will know."}}'::jsonb),

('11111111-0000-0000-0000-000000000001',
'Ralph Lauren''s Polo Bar',
'Midtown',
'Old Money',
'The most committed costume restaurant in New York, and we mean that as the highest compliment. Every surface is Ralph Lauren''s vision of American aristocracy at its most saturated. You must dress the part or you will feel you are attending the party in the wrong costume. There is no middle ground here.',
40.7612, -73.9738,
'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=800&q=80',
4,
'{"men": {"brands": ["Ralph Lauren Purple Label", "Ralph Lauren RRL", "Rolex", "Alden"], "outfit": {"top": "RL Purple Label Oxford or flannel shirt, or the equestrian cable-knit in cream — lean into the fantasy completely", "bottom": "Slim corduroy or dark denim (RRL), or proper cavalry twill trousers", "shoes": "Alden cordovan penny loafers or mahogany cap-toes — no sneakers, no exceptions", "bag": "Leather briefcase or canvas-and-leather weekend tote in cognac", "accessories": "Rolex Explorer or vintage Submariner, a subtle signet ring, canvas belt with a leather keeper"}, "color_palette": "Equestrian brown, hunter green, cream, burgundy, navy — the palette of a Connecticut stable", "budget_dupe": "RL Polo (not Purple Label) hits the aesthetic at a third of the price. Wear the exact same silhouette. The logo is acceptable here — it''s practically part of the decor."}, "women": {"brands": ["Ralph Lauren Collection", "Ralph Lauren Purple Label", "Cartier", "Manolo Blahnik"], "outfit": {"top": "Cable-knit cream sweater or a crisp white cotton blouse with subtle ruffle", "bottom": "High-waisted tweed or plaid trousers, or a midi skirt in camel", "shoes": "Riding boots or a classic block-heel in cognac leather", "bag": "Equestrian-inspired leather tote or structured satchel in saddle brown", "accessories": "Gold hoop earrings, simple pearl or gold necklace, a silk scarf at the neck or wrist"}, "color_palette": "Camel, cream, hunter green, cognac — horse country in the best possible way", "budget_dupe": "The RL Lauren or RL Polo lines for the separates — same silhouette, fraction of the price. Source a great vintage riding boot and you''ve nailed it completely."}}'::jsonb),

('11111111-0000-0000-0000-000000000001',
'The Pierre Hotel Lobby',
'Upper East Side',
'Continental',
'Find a chair near the rotunda, cross your legs, order a coffee you don''t need, and wait for someone who isn''t coming. The Pierre has been the address of quietly important people since 1930. Sit in that energy. Absorb it. Nobody will ask you to leave if you look like you belong.',
40.7681, -73.9673,
'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=800&q=80',
3,
'{"men": {"brands": ["Kiton", "Brioni", "A. Lange & Söhne", "Edward Green"], "outfit": {"top": "Fine wool or cashmere sport coat in mid-grey or camel, open collar", "bottom": "Charcoal flannel trousers, full break acceptable here — this is old school", "shoes": "Edward Green or C&J chestnut cap-toes, highly polished", "bag": "Nothing, or a slim leather portfolio", "accessories": "A. Lange & Söhne or Jaeger-LeCoultre on the wrist, a folded newspaper is a legitimate prop"}, "color_palette": "Mid-grey, charcoal, camel — the palette of a man who has had the same tailor for thirty years", "budget_dupe": "A good secondhand Zegna sport coat, well-pressed Banana Republic trousers, resoled Church''s shoes. The newspaper is free."}, "women": {"brands": ["The Row", "Max Mara", "Hermès", "Bottega Veneta"], "outfit": {"top": "Cashmere turtleneck in camel or ivory, or a silk blouse in pale champagne", "bottom": "Straight-leg wool trousers in charcoal or wide-leg cream", "shoes": "Clean pointed-toe flats or a modest heel in nude or cognac", "bag": "Hermès Kelly or Bottega Veneta Cassette — or any structured leather bag without visible logos", "accessories": "Simple gold chain, small gold studs, silk scarf folded into the collar"}, "color_palette": "Ivory, camel, champagne, pale grey — understated to the point of being a flex", "budget_dupe": "Max Mara for the coat and trousers, Cos for the blouse. A clean secondhand structured bag from a consignment shop completes it. The Pierre doesn''t care about your labels — it cares about your posture."}}'::jsonb),

('11111111-0000-0000-0000-000000000001',
'Bergdorf Goodman Ground Floor',
'Midtown',
'Luxury Retail',
'The ground floor of Bergdorf is a masterclass in civilised shopping. You are not here to buy — you are here to browse with the quiet authority of someone for whom price tags are a minor administrative detail. Linger at the jewelry counters, handle a bag, consider a scarf. Nod at things. Leave empty-handed with purpose.',
40.7639, -73.9732,
'https://images.unsplash.com/photo-1441986300917-64674bd600d8?w=800&q=80',
3,
'{"men": {"brands": ["Loro Piana", "Zegna", "Rolex", "Gucci"], "outfit": {"top": "Cashmere or merino rollneck in cream or camel, no logo", "bottom": "Dark navy or charcoal slim trousers", "shoes": "Clean white New Balance 990 or tan suede loafers — this is actually acceptable at BG", "bag": "A nice leather tote or slim backpack, nothing sporty", "accessories": "Rolex Datejust or Submariner, minimal jewelry"}, "color_palette": "Camel, navy, cream — the palette of tasteful restraint", "budget_dupe": "Uniqlo cashmere rollneck (seriously, the cashmere is excellent), well-cut trousers from J.Crew, clean leather sneakers. The store is bright; the fit matters more than the label."}, "women": {"brands": ["Toteme", "Celine", "Chanel", "The Row"], "outfit": {"top": "Silk blouse or fine-knit in neutral — nothing fast fashion, nothing with a visible designer logo (ironic given the location)", "bottom": "Tailored straight-leg trousers or a silk midi skirt", "shoes": "Clean pointed flats, kitten heel, or white sneakers if doing it the European way", "bag": "Something structured and serious — this is the one place where carrying a designer bag is not tryhard", "accessories": "Simple gold jewelry, sunglasses on top of head (indoor but acceptable here), minimal"}, "color_palette": "Ivory, champagne, dusty rose, camel — every shade of someone''s neutral closet", "budget_dupe": "Toteme separates if you can swing it. COS and Arket otherwise — the silhouettes are there. The real investment is in the bag. One good bag, worn everywhere, is the BG move."}}'::jsonb),

('11111111-0000-0000-0000-000000000001',
'The Frick Collection',
'Upper East Side',
'Intellectual',
'Henry Clay Frick built this house to house his ego and his Vermeers, and we are all beneficiaries. The garden court with its indoor fountain is the single most serene room in Manhattan. Sit there. Read nothing on your phone. Let the Fragonards watch you contemplate something they''ll assume is profound.',
40.7712, -73.9671,
'https://images.unsplash.com/photo-1560221328-12fe60f83ab8?w=800&q=80',
2,
'{"men": {"brands": ["Drake''s", "J.Press", "IWC", "Tricker''s"], "outfit": {"top": "Soft wool or tweed sport coat in earth tones, open-collar linen or chambray shirt", "bottom": "Dark olive or tobacco chino, no crease necessary", "shoes": "Suede chukka boots or brown brogues, well-worn is fine", "bag": "Leather satchel or worn canvas tote — something that says ''I also own a lot of books''", "accessories": "IWC Portofino or a vintage dress watch, thin wire-rimmed glasses help the look enormously"}, "color_palette": "Tobacco, olive, rust, camel — the palette of someone whose apartment smells like old paper and is intentional about it", "budget_dupe": "J.Crew and Banana Republic hit the intellectual-moneyed aesthetic reliably. A $40 thrifted sport coat from a proper thrift store beats a new one at 5x the price. The Frick is forgiving."}, "women": {"brands": ["A.P.C.", "Isabel Marant", "Cartier", "Sézane"], "outfit": {"top": "Fine-knit turtleneck in rust or camel, or a silk blouse in forest green", "bottom": "Wide-leg linen or wool trousers, or a midi skirt in a muted print", "shoes": "Ankle boots in cognac leather or simple leather loafers", "bag": "Worn leather tote or a structured satchel — something that could plausibly carry a Phaidon monograph", "accessories": "Gold hoop earrings, a stack of thin gold rings, minimal necklace"}, "color_palette": "Rust, forest green, cognac, ivory — the palette of someone with strong opinions about Velázquez", "budget_dupe": "Sézane does the intellectual-chic thing well at accessible prices. A vintage leather tote from a thrift store or eBay completed the look. The glasses — even clear lenses — are a legitimate prop."}}'::jsonb),

('11111111-0000-0000-0000-000000000001',
'Cipriani Downtown',
'SoHo',
'Art World',
'The most see-and-be-seen lunch in downtown New York. The room is enormous, white, and soaked in the kind of light that makes everyone look like they have a place in the Hamptons. You''re here because you''re someone, or because you''re sitting next to someone, or because you want to appear to be either. All three are valid.',
40.7202, -74.0051,
'https://images.unsplash.com/photo-1537047902294-62a40c20a6ae?w=800&q=80',
5,
'{"men": {"brands": ["Rick Owens", "Chrome Hearts", "AP", "Saint Laurent"], "outfit": {"top": "All-black everything, or a white Saint Laurent dress shirt open three buttons. No in-between.", "bottom": "Black slim trousers or dark-wash straight jeans, no distressing", "shoes": "Black leather Chelsea boots or clean white sneakers — Rick Owens Ramones if you have them", "bag": "Black leather tote or nothing", "accessories": "Audemars Piguet Royal Oak, Chrome Hearts ring or cross necklace, matte black sunglasses worn inside"}, "color_palette": "Black, white, maybe one item in deep burgundy or camel if you''re feeling experimental. This is downtown.", "budget_dupe": "All-black COS or Uniqlo, done seriously. The Chrome Hearts cross necklace can be duped. The AP cannot, but a black leather strap on a vintage watch reads well from distance."}, "women": {"brands": ["The Row", "Bottega Veneta", "Celine", "Jacquemus"], "outfit": {"top": "Silk slip top or a structured blazer with nothing underneath — pick one and commit", "bottom": "Wide-leg black trousers or a bias-cut midi slip skirt", "shoes": "Barely-there heeled sandal in nude or a serious black boot", "bag": "Bottega Veneta Jodie or Celine 16 — something that costs more than appears and says exactly that", "accessories": "Minimal — one statement ring, small gold hoops, sunglasses you don''t take off"}, "color_palette": "Black, ivory, caramel, deep burgundy — the palette of someone who treats getting dressed as a curatorial decision", "budget_dupe": "The Row''s silhouettes at Zara''s prices exists: look at Toteme or COS for structured basics. Source the bag secondhand. One authentic luxury bag does more for the Cipriani read than five budget items."}}'::jsonb),

('11111111-0000-0000-0000-000000000001',
'The Morgan Library & Museum',
'Murray Hill',
'Intellectual',
'J.P. Morgan''s private library, now public, is one of the great rooms of the world. The triple-tiered East Room with its red silk walls and original manuscripts will make you feel both culturally elevated and slightly unworthy — which is exactly how Morgan intended it. Browse the reading room like you come here to think.',
40.7493, -73.9816,
'https://images.unsplash.com/photo-1481627834876-b7833e8f5570?w=800&q=80',
2,
'{"men": {"brands": ["Drake''s", "Rubinacci", "Nomos Glashütte", "Church''s"], "outfit": {"top": "A soft herringbone or houndstooth sport coat, or a well-worn corduroy blazer", "bottom": "Dark grey flannels or slim dark chino", "shoes": "Dark suede loafers or leather lace-ups in dark tan or brown", "bag": "A leather briefcase or book bag — something that suggests you arrived with reading material", "accessories": "Nomos Club or any clean dress watch, round glasses, a folded pocket square in muted print"}, "color_palette": "Herringbone grey, tobacco, dark tan — the palette of a man who owns first editions and is not shy about it", "budget_dupe": "A good tweed sport coat from a thrift store is perfect here — worn-in is better than pristine. The Morgan is not a fashion context. It''s a posture context."}, "women": {"brands": ["A.P.C.", "Lemaire", "Hermès", "Repetto"], "outfit": {"top": "Simple cashmere in dusty rose or sage, or a soft cotton blouse with literary-print detail", "bottom": "High-waisted straight trousers in khaki or a long A-line skirt in deep plum", "shoes": "Flat leather ballerinas (Repetto is appropriate) or ankle boots in cognac", "bag": "A worn leather tote or structured book bag — something practical enough to hold a catalogue", "accessories": "Small gold studs, thin gold bracelet, silk scarf loosely tied"}, "color_palette": "Dusty rose, sage, plum, cognac — the palette of a well-curated personal library", "budget_dupe": "Sézane and A.P.C. sale items get you directly to this aesthetic. The Morgan is about quiet confidence, not visible spend. Wear things you love, pressed well."}}'::jsonb),

('11111111-0000-0000-0000-000000000001',
'Central Park Reservoir Path',
'Upper West Side',
'Weekend Aristocrat',
'The 1.58-mile loop around the Jacqueline Kennedy Onassis Reservoir is the most democratic space in the city where everyone still somehow looks like they have money. This is the Saturday morning of someone who brunch-books six weeks out. Walk purposefully. Do not jog unless your form is excellent.',
40.7851, -73.9626,
'https://images.unsplash.com/photo-1534430480872-3498386e7856?w=800&q=80',
2,
'{"men": {"brands": ["Lululemon", "Vuori", "AP", "On Running"], "outfit": {"top": "Oatmeal or charcoal quarter-zip in technical fabric or merino — no graphic tees", "bottom": "Slim tapered joggers or running shorts in navy or charcoal", "shoes": "On Running Cloudmonster or New Balance 1080 — clean, not neon", "bag": "Small running vest or nothing", "accessories": "Apple Watch Ultra (the titanium one), AirPods Pro, thin running cap in neutral"}, "color_palette": "Oatmeal, charcoal, navy — athletic without announcing it", "budget_dupe": "Uniqlo active gear is genuinely excellent and indistinguishable in motion. Clean New Balance are the everyman''s On Running. The watch matters more than the clothes at the reservoir."}, "women": {"brands": ["Alo Yoga", "Lululemon", "Cartier", "On Running"], "outfit": {"top": "Fitted crop top or tank in muted sage, dusty rose, or bone — nothing neon, nothing graphic", "bottom": "High-waisted leggings in charcoal or deep olive, full-length", "shoes": "On Running Cloudstratus or Hoka Clifton in a neutral colorway", "bag": "A small crossbody running pouch or nothing", "accessories": "Cartier Love bracelet (worn running — the flex is intentional), simple stud earrings, a clean cap or ponytail"}, "color_palette": "Sage, dusty rose, bone, charcoal — the palette of an uptown woman who takes her wellness seriously", "budget_dupe": "Lululemon Align leggings are worth full price for this LARP. Everything else can be generic. The Love bracelet can be the gold CZ version from Mejuri — at speed, nobody''s verifying."}}'::jsonb),

('11111111-0000-0000-0000-000000000001',
'Lever House Restaurant',
'Midtown',
'Power Lunch',
'The glass curtain wall of the 1952 Lever House is a landmark; the restaurant inside is a power lunch circuit staple. You are here between noon and 2pm on a Tuesday, and you are discussing something important that you won''t disclose. Order the steak. Use the name of whoever you''re meeting before they say it. This is performance.',
40.7576, -73.9720,
'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=800&q=80',
4,
'{"men": {"brands": ["Brioni", "Kiton", "Patek Philippe", "Berluti"], "outfit": {"top": "Dark navy or charcoal suit — the suit is non-negotiable. Spread collar, French cuff.", "bottom": "Matching suit trousers, no break", "shoes": "Black or dark burgundy Oxfords, blinding shine", "bag": "Slim leather portfolio or structured attaché", "accessories": "Patek Philippe Nautilus or Grand Complications — the watch is doing 40% of the work here. Tie is optional but a silk pocket square is not."}, "color_palette": "Navy, charcoal, white, burgundy — the palette of a midtown office forty floors up", "budget_dupe": "SuitSupply Napoli cut is genuinely excellent. A polished vintage Omega on leather strap and a real leather portfolio from TJ Maxx (yes) completes the read. The Lever House is dark inside — fabric quality is less visible than fit."}, "women": {"brands": ["Gabriela Hearst", "Max Mara", "Rolex", "Bottega Veneta"], "outfit": {"top": "A structured blazer in deep navy or charcoal, or a silk blouse under a sharp jacket", "bottom": "Tailored wide-leg trousers or a pencil skirt — this is a power context", "shoes": "Pointed-toe block heel or clean flat in black or dark navy", "bag": "Structured top-handle — Bottega Veneta or Polene if budget is a reality", "accessories": "Rolex Datejust or Cartier Ballon Bleu, minimal jewelry, one serious ring"}, "color_palette": "Navy, black, ivory — the palette of someone who makes decisions", "budget_dupe": "A sharp blazer from Banana Republic Monogram, well-cut trousers from Mango, one real watch. The bag can be Polene — it photographs as expensive and holds up to scrutiny."}}'::jsonb),

('11111111-0000-0000-0000-000000000001',
'The Mark Hotel',
'Upper East Side',
'Continental',
'Jean-Georges Vongerichten''s restaurant occupies this Upper East Side hotel with an assurance that the neighborhood deserves nothing less. The bar area on a Thursday evening is the place. You are waiting for someone, or you just arrived from somewhere. Either way you are in no hurry. That is the entire point.',
40.7756, -73.9637,
'https://images.unsplash.com/photo-1543007630-9710e4a00a20?w=800&q=80',
4,
'{"men": {"brands": ["Tom Ford", "Canali", "Rolex", "Loro Piana"], "outfit": {"top": "Cashmere rollneck in dark navy or black under a slim blazer — or a crisp shirt with no tie", "bottom": "Dark slim trousers, impeccable", "shoes": "Suede loafers in tan or black patent if feeling formal", "bag": "Nothing. A man at The Mark does not carry a bag to the bar.", "accessories": "Rolex Datejust or vintage Omega Constellation, one signet ring maximum"}, "color_palette": "Black, navy, champagne — evening elegance without the effort of explaining yourself", "budget_dupe": "A slim dark blazer from COS over an Uniqlo merino rollneck is the move. Dark trousers pressed with a crease. Suede loafers from Thursday Boots (surprisingly credible). Nobody asks where you bought it at The Mark."}, "women": {"brands": ["Roland Mouret", "Victoria Beckham", "Cartier", "Jimmy Choo"], "outfit": {"top": "Structured shift dress in midnight navy or champagne — something that required intention", "bottom": "(built into the dress)", "shoes": "Pointed slingback or strappy sandal heel — something that makes noise on the marble", "bag": "Small clutch or micro bag in satin or leather, something precious", "accessories": "Cartier or Bulgari thin bracelet stack, drop earrings in gold, a spritz of something expensive you wear lightly"}, "color_palette": "Midnight navy, champagne, ivory — cocktail hour made serious", "budget_dupe": "The Reformation does structured midi dresses that read luxury from across a marble lobby. A secondhand small designer bag and a real gold bracelet (even a thin one) transforms the rest."}}'::jsonb),

('11111111-0000-0000-0000-000000000001',
'Sant Ambroeus',
'Upper East Side',
'Power Lunch',
'The most reliably Upper East Side lunch in the Upper East Side. The coffee is Milanese and so is the attitude. You know the maître d'' by first name or you know someone who does. Either way you got a table on short notice and you''re not making a point of it. Eat the pasta. Know things about the pasta.',
40.7710, -73.9641,
'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=800&q=80',
3,
'{"men": {"brands": ["Zegna", "Brunello Cucinelli", "Rolex", "Tod''s"], "outfit": {"top": "Lightweight cashmere sport coat over a fine merino or linen shirt", "bottom": "Warm grey flannels or dark slim chino", "shoes": "Suede driving loafers (Tod''s are literally appropriate here) or clean leather moccasins", "bag": "Nothing, or a newspaper folded under the arm", "accessories": "Rolex Explorer or vintage Omega, a very subtle bracelet or signet ring"}, "color_palette": "Camel, warm grey, ivory — an Italian edit of American prep", "budget_dupe": "The Sant Ambroeus aesthetic is about Italian ease. Linen shirt + slim khakis + suede loafers from Thursday Boots achieves it at a sixth of the price. The coffee order matters as much as the clothes."}, "women": {"brands": ["Loro Piana", "Toteme", "Hermès", "The Row"], "outfit": {"top": "Silk blouse in a muted geometric print or a fine-knit cream jumper", "bottom": "High-waisted trousers in camel or warm grey, or a wrap skirt in silk", "shoes": "Flat leather mule or low block heel — Italian shoes preferred", "bag": "Hermès Lindy or Garden Party, or a quality leather tote without logos", "accessories": "Silk scarf at the neck or wrist, thin gold chain, simple gold hoops"}, "color_palette": "Ivory, camel, warm grey, Hermès orange (if you have the bag) — Milan as imagined by the Upper East Side", "budget_dupe": "A silk blouse from & Other Stories + Toteme-dupe trousers from Cos + flat Italian-style mules from Mango. The scarf can be vintage from a flea market. The Italian look is in the ease, not the price."}}'::jsonb),

('11111111-0000-0000-0000-000000000001',
'The Odeon',
'TriBeCa',
'Art World',
'The brasserie that launched a neighborhood. Since 1980, The Odeon has been where the art world, the literary world, and the people-who-know-both worlds collide over steak frites and Côtes du Rhône at 11pm on a Wednesday. Dress with intention but not effort. Those are different things.',
40.7170, -74.0092,
'https://images.unsplash.com/photo-1537047902294-62a40c20a6ae?w=800&q=80',
3,
'{"men": {"brands": ["A.P.C.", "Acne Studios", "Cartier", "Common Projects"], "outfit": {"top": "A good white tee or fine-knit navy long-sleeve under an unstructured linen or cotton blazer", "bottom": "Dark slim jeans (A.P.C. Petit New Standard are canon here) or dark slim chino", "shoes": "White Common Projects Achilles or clean suede loafers", "bag": "Nothing or a worn canvas tote", "accessories": "Cartier Santos or a vintage watch on NATO strap, minimal"}, "color_palette": "Navy, white, dark denim — downtown with a nod to uptown money", "budget_dupe": "The Odeon crowd doesn''t actually care about labels. An unstructured blazer from Cos, good dark jeans, clean white sneakers. The confidence of not trying too hard is literally free."}, "women": {"brands": ["Isabel Marant", "Jacquemus", "APM Monaco", "Sandro"], "outfit": {"top": "Effortless silk blouse with one button undone or a fitted knit top", "bottom": "High-waist straight denim or a short flirty mini skirt in a solid", "shoes": "Block heel ankle boot or a sandal with minimal straps", "bag": "Small crossbody or clutch — something you could stuff in a coat pocket", "accessories": "Layered thin gold chains, small hoop earrings, one bold ring"}, "color_palette": "Black, ivory, a pop of warm terracotta or deep burgundy — downtown evening ease", "budget_dupe": "Sandro and Maje hit this exact aesthetic and are sold in SoHo. The trick is: press nothing, iron nothing, let it be slightly rumpled. The Odeon look is deliberate carelessness."}}'::jsonb),

('11111111-0000-0000-0000-000000000001',
'Balthazar',
'SoHo',
'Continental',
'Keith McNally''s eternal brasserie has been the center of the SoHo universe since 1997 and will be long after the rest of us are gone. Weekend brunch is a full-contact sport. The dinner service is more civilised. Either way you are eating steak frites, you are drinking Muscadet, and you are people-watching with the focus of a documentarian.',
40.7228, -74.0007,
'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=800&q=80',
3,
